contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint addAmount, bool doWithdraw) public payable {
        require(true);
        // ensure we have funds to forward when needed
        if (addAmount > 0) {
            require(address(this).balance >= addAmount, "insufficient test balance");
        }

        // Read initial observed values
        uint beforeContractBal = address(c).balance;
        uint beforeUserBal = c.getBalance(address(this));

        // Try calling addToBalance with provided amount; capture revert
        bool addReverted;
        if (addAmount > 0) {
            try c.addToBalance{value: addAmount}() {
                addReverted = false;
            } catch {
                addReverted = true;
            }
        } else {
            // calling with zero value is allowed; still try
            try c.addToBalance{value: 0}() {
                addReverted = false;
            } catch {
                addReverted = true;
            }
        }

        uint afterAddContractBal = address(c).balance;
        uint afterAddUserBal = c.getBalance(address(this));

        // If add succeeded, contract balance and reported balance should have increased by addAmount
        bool addInvariant = addReverted ? (afterAddContractBal == beforeContractBal && afterAddUserBal == beforeUserBal)
                                        : (afterAddContractBal == beforeContractBal + addAmount && afterAddUserBal == beforeUserBal + addAmount);

        // Optionally attempt withdraw; capture revert
        bool withdrawReverted;
        uint beforeWithdrawContractBal = afterAddContractBal;
        uint beforeWithdrawUserBal = afterAddUserBal;

        if (doWithdraw) {
            try c.withdrawBalance() {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
        } else {
            // don't call withdraw
            withdrawReverted = true; // treat as not executed
        }

        uint afterWithdrawContractBal = address(c).balance;
        uint afterWithdrawUserBal = c.getBalance(address(this));

        // If withdraw was executed and succeeded, the recorded user balance must become zero and contract balance must decrease by the previous recorded amount
        bool withdrawInvariant;
        if (doWithdraw && !withdrawReverted) {
            // amount withdrawn equals prior recorded user balance
            uint expectedDecrease = beforeWithdrawUserBal;
            withdrawInvariant = (afterWithdrawUserBal == 0) && (afterWithdrawContractBal + expectedDecrease == beforeWithdrawContractBal);
        } else if (doWithdraw && withdrawReverted) {
            // state should be unchanged by a reverted withdraw
            withdrawInvariant = (afterWithdrawContractBal == beforeWithdrawContractBal) && (afterWithdrawUserBal == beforeWithdrawUserBal);
        } else {
            // withdraw not attempted: state unchanged
            withdrawInvariant = (afterWithdrawContractBal == beforeWithdrawContractBal) && (afterWithdrawUserBal == beforeWithdrawUserBal);
        }

        // Final general assertion combining both invariants
        assert(addInvariant && withdrawInvariant);
    }

    receive() external payable {
        // allow receiving Ether from C during withdraw
    }
}

