        require(address(this).balance >= amount);

        // read initial observable values
        uint256 beforeContractRecorded = c.getBalance(address(this));
        uint256 beforeCbalance = address(c).balance;
        uint256 beforeThisBalance = address(this).balance;

        // perform addToBalance sending `amount` wei
        bool addReverted;
        try c.addToBalance{value: amount}() {
            addReverted = false;
        } catch {
            addReverted = true;
        }

        // read values after add
        uint256 afterAddRecorded = c.getBalance(address(this));
        uint256 afterAddCbalance = address(c).balance;
        uint256 afterAddThisBalance = address(this).balance;

        // perform withdrawBalance
        bool withdrawReverted;
        try c.withdrawBalance() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // read values after withdraw
        uint256 finalRecorded = c.getBalance(address(this));
        uint256 finalCbalance = address(c).balance;
        uint256 finalThisBalance = address(this).balance;

        // We assert the general property: if neither call reverted, then
