                // simplified: when neither reverted this becomes beforeThisBalance - amount + amount == beforeThisBalance
                // but using the general form above covers revert branches; additionally require C's balance decreased by amount
                finalCbalance + amount == beforeCbalance
            )
        );
    }

    // allow receiving Ether during withdraw
    receive() external payable { }
}

